steps.script:
GameState.state.players["1"]["cp"] = 0
GameState.state.players["2"]["cp"] = 0
var xs := [1500.0, 1572.0, 1645.0]
var ms = GameState.state.units["U_ALLARUS_CUSTODIANS_A"].models
for i in range(ms.size()):
	ms[i]["position"] = {"x": xs[i % 3], "y": 1700.0}
tree.current_scene._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_ALLARUS_CUSTODIANS_A", GameState.state)

var fp = PhaseManager.get_current_phase_instance()
for uid in GameState.state.units:
	if fp.sequencer_11e.eligible_to_fight(uid, GameState.state):
		fp.sequencer_11e.mark_fought(uid, GameState.state)
return fp.get_end_fight_status().step_over

var ph = PhaseManager.get_current_phase_instance()
if ph.get_pending_stratagem_window_decider() == 1:
	tree.root.get_node("StratagemDialog/Content/DeclineButton").pressed.emit()
return true
